PRAGMA foreign_keys = ON;
CREATE TABLE condominiums (id TEXT PRIMARY KEY, name TEXT NOT NULL, address TEXT NOT NULL, fiscal_year INTEGER NOT NULL);
CREATE TABLE users (id TEXT PRIMARY KEY, name TEXT NOT NULL);
CREATE TABLE memberships (user_id TEXT NOT NULL REFERENCES users(id), condominium_id TEXT NOT NULL REFERENCES condominiums(id), role TEXT NOT NULL CHECK(role IN ('manager','owner')), revoked_at TEXT, PRIMARY KEY(user_id, condominium_id));
CREATE TABLE lots (id TEXT PRIMARY KEY, condominium_id TEXT NOT NULL REFERENCES condominiums(id), number TEXT NOT NULL, label TEXT NOT NULL, owner_id TEXT REFERENCES users(id), weight INTEGER NOT NULL CHECK(weight > 0), UNIQUE(condominium_id,number));
CREATE TABLE records (id TEXT PRIMARY KEY, condominium_id TEXT NOT NULL REFERENCES condominiums(id), kind TEXT NOT NULL CHECK(kind IN ('incident','assembly','fund','document')), title TEXT NOT NULL, audience TEXT NOT NULL CHECK(audience IN ('shared','management','lot')), lot_id TEXT REFERENCES lots(id), payload TEXT NOT NULL CHECK(json_valid(payload)), version INTEGER NOT NULL DEFAULT 1, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, updated_by TEXT NOT NULL REFERENCES users(id), CHECK((audience='lot' AND lot_id IS NOT NULL) OR (audience!='lot' AND lot_id IS NULL)));
CREATE INDEX records_context ON records(condominium_id,kind,updated_at);
CREATE TABLE document_versions (id TEXT PRIMARY KEY, record_id TEXT NOT NULL REFERENCES records(id), object_key TEXT NOT NULL UNIQUE, filename TEXT NOT NULL, mime TEXT NOT NULL, size INTEGER NOT NULL, sha256 TEXT NOT NULL, state TEXT NOT NULL CHECK(state IN ('pending','ready','failed')), created_at TEXT NOT NULL, author_id TEXT NOT NULL REFERENCES users(id));
CREATE TABLE audit (id INTEGER PRIMARY KEY AUTOINCREMENT, condominium_id TEXT NOT NULL, actor_id TEXT NOT NULL, action TEXT NOT NULL, resource_id TEXT NOT NULL, version INTEGER NOT NULL, happened_at TEXT NOT NULL);
CREATE TRIGGER record_created AFTER INSERT ON records BEGIN INSERT INTO audit(condominium_id,actor_id,action,resource_id,version,happened_at) VALUES(NEW.condominium_id,NEW.updated_by,'created',NEW.id,NEW.version,NEW.updated_at); END;
CREATE TRIGGER record_updated AFTER UPDATE ON records BEGIN INSERT INTO audit(condominium_id,actor_id,action,resource_id,version,happened_at) VALUES(NEW.condominium_id,NEW.updated_by,'updated',NEW.id,NEW.version,NEW.updated_at); END;
